    </template>
    <template v-else-if="data">
      <section v-if="['overview','budgets','allocations','funds','grants','expenses','approvals','payments','reports'].includes(section)" class="finance-metrics"><article v-for="m in metrics" :key="m.label"><small>{{ m.label }}</small><strong :class="{negative:m.amount<0}">{{ money(m.amount) }}</strong><span>{{ m.hint }}</span></article></section>
      <template v-if="['overview','reports','budgets'].includes(section)"><div class="finance-two-col"><section class="finance-panel"><header><h2>Program budget vs. spending</h2><span class="finance-legend">● Paid <span>● Committed</span></span></header><div v-for="p in programSummary" :key="p.id" class="finance-program-bar"><div><strong>{{ p.name }}</strong><small>{{ money(p.paid) }} paid · {{ money(p.committed) }} committed / {{ money(p.budget) }}</small></div><div class="finance-progress"><i :style="{width:percent(p.paid,p.budget)+'%'}"/><i class="committed" :style="{width:percent(p.committed,p.budget)+'%'}"/></div><small>{{ money(p.budget-p.paid-p.committed) }} available</small></div><p v-if="!programSummary.length" class="finance-empty">Create programs and budgets to see spending here.</p></section><section class="finance-panel"><h2>{{ portal?'Your next steps':'Needs attention' }}</h2><button class="finance-next" @click="go('expenses')"><span>Expense requests awaiting review</span><b>{{ pendingExpenses.length }}</b></button><button class="finance-next" @click="go('reports')"><span>Open reporting requirements</span><b>{{ reporting.length }}</b></button><button class="finance-next" @click="go('payments')"><span>Approved / scheduled payments</span><b>{{ payableExpenses.length }}</b></button><p class="finance-callout">Available to spend subtracts both paid expenses and outstanding approved commitments. Awarded funding and received cash are tracked separately.</p><button v-if="data.role!=='viewer'" class="primary" @click="formKind='expenses'">Submit an expense request</button></section></div></template>
